import{c as a,S as t,j as r,m as o}from"./chunks/framework.C68YPdek.js";const p=JSON.parse('{"title":"Evaluators","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/evaluators.md","filePath":"developer/architecture/evaluators.md"}'),n={name:"developer/architecture/evaluators.md"};function d(s,e,l,c,i,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="evaluators" tabindex="-1">Evaluators <a class="header-anchor" href="#evaluators" aria-label="Permalink to “Evaluators”">​</a></h1><p>An <strong>evaluator</strong> runs programs of one language, as a <a href="./conductor">Conductor</a> runner: in a Web Worker in the browser, and in a worker thread in the <a href="./grader">grader</a>. The <a href="./directories">language directory</a> names each evaluator and gives the URL of its entry file. Checked against the language directory and the repositories on 28 November 2026.</p><table tabindex="0"><thead><tr><th>Language</th><th>Repository</th><th>Notes</th></tr></thead><tbody><tr><td>Source §1 to §4 (sublanguages of JavaScript)</td><td><a href="https://github.com/source-academy/js-slang" target="_blank" rel="noreferrer"><code>js-slang</code></a></td><td>A default evaluator per chapter, plus evaluators that offer a tool: the Stepper (§1, §2) and the CSE machine (§3, §4). The language documentation is published at <a href="https://docs.sourceacademy.org/javascript" target="_blank" rel="noreferrer">https://docs.sourceacademy.org/javascript</a></td></tr><tr><td>Python §1 to §4, §4 Typed, full Python</td><td><a href="https://github.com/source-academy/py-slang" target="_blank" rel="noreferrer"><code>py-slang</code></a></td><td>Several evaluators per chapter: Python compiled to JavaScript, a virtual machine (PVML), WebAssembly, CPython through Pyodide, and ones for the Stepper, the E-Stepper and the CSE machine. Documentation: <a href="https://docs.sourceacademy.org/python" target="_blank" rel="noreferrer">https://docs.sourceacademy.org/python</a></td></tr><tr><td>Scheme</td><td><a href="https://github.com/source-academy/scm-slang" target="_blank" rel="noreferrer"><code>scm-slang</code></a></td><td>One evaluator</td></tr><tr><td>Java</td><td><a href="https://github.com/source-academy/java-slang" target="_blank" rel="noreferrer"><code>java-slang</code></a></td><td>One evaluator; a Java parser and runtime in TypeScript</td></tr><tr><td>OCaml</td><td><a href="https://github.com/source-academy/ocaml-slang" target="_blank" rel="noreferrer"><code>ocaml-slang</code></a></td><td>The real OCaml toplevel, Menhir and ocamllex, compiled to JavaScript and run in a worker</td></tr></tbody></table><p>Other repositories contain language implementations that are not in the language directory today (for example <code>pie-slang</code> for Pie, <code>c-slang</code> for C, and <code>sinter</code> and <code>pynter</code> for microcontrollers).</p><h2 id="what-an-evaluator-provides" tabindex="-1">What an evaluator provides <a class="header-anchor" href="#what-an-evaluator-provides" aria-label="Permalink to “What an evaluator provides”">​</a></h2><ul><li>An entry file that creates a <code>Conduit</code> and registers the runner plugin with the evaluator (see <a href="./conductor">Conductor</a>), published on GitHub Pages.</li><li>The implementation of <code>IEvaluator</code>: evaluating chunks and files, sending results, errors and output.</li><li>For a tool, the evaluator&#39;s side of the plugin: the <code>runner-*</code> package, whose base class turns the evaluator&#39;s steps into messages on the plugin&#39;s channel. See <a href="./../writing-a-visualizer-plugin">Writing a visualizer plugin</a>.</li><li>Support for modules, through the Conductor module interface.</li></ul><h2 id="two-copies-of-an-evaluator" tabindex="-1">Two copies of an evaluator <a class="header-anchor" href="#two-copies-of-an-evaluator" aria-label="Permalink to “Two copies of an evaluator”">​</a></h2><p>The browser loads an evaluator from its GitHub Pages site. The grader keeps a vendored copy (see <a href="./grader">Grader</a>). A fix to an evaluator reaches grading only when the copy is updated.</p>',8)])])}const g=a(n,[["render",d]]);export{p as __pageData,g as default};
